begin;
do $test$
declare uid uuid; quiz uuid; game record; a record; b record; q1 uuid; q2 uuid; s jsonb; rejected boolean; begin
select id into uid from auth.users limit 1; if uid is null then raise exception 'No host account'; end if;
perform set_config('request.jwt.claim.sub',uid::text,true);
quiz:=public.save_quiz('TEST Quiz Royale',0,'[{"text":"Test 1","options":["A","B","C","D"],"correct_option":0},{"text":"Test 2","options":["A","B","C","D"],"correct_option":1}]'::jsonb);
select * into game from public.create_game(quiz);
select id into q1 from public.questions where quiz_id=quiz and position=1;
select id into q2 from public.questions where quiz_id=quiz and position=2;
if q1 is null or q2 is null then raise exception 'Position repair failed'; end if;
select * into a from public.join_game(game.join_code,'Test Queen A');select * into b from public.join_game(game.join_code,'Test Queen B');
rejected:=false;begin perform public.join_game(game.join_code,'test queen a'); exception when others then rejected:=true;end;if not rejected then raise exception 'Duplicate nickname accepted';end if;
perform public.start_game(game.game_id);
perform set_config('request.jwt.claim.sub','',true);
s:=public.royale_state(game.join_code,a.player_id,a.session_token);
if s->'question' ? 'correct' then raise exception 'Answer exposed before reveal';end if;
rejected:=false;begin perform public.royale_answer(game.game_id,a.player_id,'invalid',q1,0);exception when others then rejected:=true;end;if not rejected then raise exception 'Forged session accepted';end if;
rejected:=false;begin perform public.royale_answer(game.game_id,a.player_id,a.session_token,q2,1);exception when others then rejected:=true;end;if not rejected then raise exception 'Future question accepted';end if;
perform public.royale_answer(game.game_id,a.player_id,a.session_token,q1,0);
perform public.royale_answer(game.game_id,a.player_id,a.session_token,q1,1);
perform public.royale_answer(game.game_id,b.player_id,b.session_token,q1,1);
s:=public.royale_state(game.join_code,a.player_id,a.session_token);
if (s->>'my_score')::int<>100 or (s->>'my_answer')::int<>0 or (s->>'answered')::int<>2 then raise exception 'Duplicate scoring or response mismatch';end if;
rejected:=false;begin perform public.royale_control(game.game_id,'reveal',1,false);exception when others then rejected:=true;end;if not rejected then raise exception 'Unauthorized host accepted';end if;
perform set_config('request.jwt.claim.sub',uid::text,true);
perform public.royale_control(game.game_id,'reveal',1,false);
perform set_config('request.jwt.claim.sub','',true);
s:=public.royale_state(game.join_code);if (s->'question'->>'correct')::int<>0 then raise exception 'Reveal failed';end if;
perform set_config('request.jwt.claim.sub',uid::text,true);perform public.royale_control(game.game_id,'next',1,true);
rejected:=false;begin perform public.royale_control(game.game_id,'next',1,true);exception when others then rejected:=true;end;if not rejected then raise exception 'Stale command accepted';end if;
update public.quizzes set question_time=10 where id=quiz;update public.games set question_started_at=clock_timestamp()-interval '11 seconds' where id=game.game_id;
rejected:=false;begin perform public.royale_answer(game.game_id,a.player_id,a.session_token,q2,1);exception when others then rejected:=true;end;if not rejected then raise exception 'Expired answer accepted';end if;
update public.quizzes set question_time=0 where id=quiz;
perform public.royale_answer(game.game_id,a.player_id,a.session_token,q2,1);perform public.royale_answer(game.game_id,b.player_id,b.session_token,q2,1);
perform public.royale_control(game.game_id,'reveal',2,false);perform public.royale_control(game.game_id,'next',2,true);
s:=public.royale_state(game.join_code,a.player_id,a.session_token);if s->>'status'<>'finished' or (s->>'my_score')::int<>200 then raise exception 'Final state incorrect';end if;
if has_function_privilege('anon','public.royale_control(uuid,text,integer,boolean)','execute') then raise exception 'Anonymous host permissions';end if;
if not has_function_privilege('anon','public.royale_answer(uuid,uuid,text,uuid,integer)','execute') then raise exception 'Players cannot submit';end if;
end $test$;
rollback;
select 'PASS: two players, positions, nicknames, hidden answer, tokens, question isolation, idempotency, scoring, host authorization, reveal, stale controls, deadline, unlimited time, finish, grants. All test data rolled back.' as test_result;